def calculate_an(n, a):
    if n == 1:
        return 0

    max_val = -float('inf')
    for i in range(1, n):
        # Term = a_i + a_{n-i} + min(i, n-i)
        term = a[i] + a[n - i] + min(i, n - i)
        if term > max_val:
            max_val = term

    return max_val

# Initialize sequence storage. a[n] holds a_n. Index 0 is unused.
a = [0] * 21 
a[1] = 0

for n in range(2, 21):
    a[n] = calculate_an(n, a)

print("n | a_n")
for n in range(1, 21):
    print(f"{n:2} | {a[n]}")
